// Tests for the repair-command graders in evals/drift-repairs and evals/quoted-repair.
//
//   node --test scripts/skill-evals/repair-graders.test.mjs
//
// The patterns are read from the case files themselves, so what is pinned here is what both eval
// runners (Codex through graders.mjs, Claude through `claude plugin eval`) grade with. They are
// generated by command-grammar.mjs; the first test fails when a case file and the generator
// disagree. The negative controls are commands refs rejects, commands that would edit something
// else, or files that are not exactly one command: each must FAIL its grader. Nothing here is ever
// executed; the hostile strings are only graded.

import { GRAMMARS, commandPattern, staleGraders } from './command-grammar.mjs';
import { deepStrictEqual, strictEqual } from 'node:assert/strict';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { grade } from './graders.mjs';
import { join } from 'node:path';
import { test } from 'node:test';
import { tmpdir } from 'node:os';

// Just enough YAML for one grader entry: single-quoted scalars and a one-line flow mapping. The
// workflow job that runs this has no install, so a YAML library is not an option.
const scalar = (raw) => {
  const quoted = /^'(?<body>.*)'$/su.exec(raw)?.groups.body;
  return quoted === undefined ? raw.trim() : quoted.replaceAll("''", "'");
};

const targetOf = (raw) => {
  const path = /path: (?<path>[^ }]+)/u.exec(raw)?.groups.path;
  return path === undefined ? scalar(raw) : { path, source: 'file' };
};

const fieldOf = (line) => {
  const field = /^ {4}(?<key>pattern|match|target): (?<value>.*)$/u.exec(line)?.groups;
  if (field === undefined) {
    return {};
  }
  return { [field.key]: field.key === 'target' ? targetOf(field.value) : scalar(field.value) };
};

const graderFrom = async (caseName, name) => {
  const text = await readFile(new URL(`../../evals/${caseName}/case.yaml`, import.meta.url), 'utf8');
  const lines = text.split('\n');
  const start = lines.indexOf(`  - name: ${name}`) + 1;
  const length = lines.slice(start).findIndex((line) => !line.startsWith('    '));
  const grader = { name, type: 'regex' };
  for (const line of lines.slice(start, start + length)) {
    Object.assign(grader, fieldOf(line));
  }
  strictEqual(typeof grader.pattern, 'string', `${caseName} has a grader ${name} with a pattern`);
  return grader;
};

const inFile = async (grader, content) => {
  const cwd = await mkdtemp(join(tmpdir(), 'refs-grader-'));
  try {
    await writeFile(join(cwd, grader.target.path), content);
    const result = await grade(grader, { commands: [], cwd, lastMessage: content, trace: '' });
    return result.passed;
  } finally {
    await rm(cwd, { force: true, recursive: true });
  }
};

// The contents whose grade is not `expected`, so a failure names them.
const misgraded = async (grader, contents, expected) => {
  const grades = await Promise.all(contents.map((content) => inFile(grader, content)));
  return contents.filter((_content, index) => grades[index] !== expected);
};

test('the case files carry the patterns command-grammar.mjs generates', async () => {
  deepStrictEqual(await staleGraders(), []);
});

test('every generated grader reads a command file, never the reply', async () => {
  const graders = await Promise.all(
    Object.entries(GRAMMARS).flatMap(([caseName, names]) =>
      Object.keys(names).map((name) => graderFrom(caseName, name)),
    ),
  );
  deepStrictEqual(
    graders.filter((grader) => grader.target?.source !== 'file').map((grader) => grader.name),
    [],
  );
});

const MOVE = "refs edit 'local/fixtures/toolkit' --package='@toolkit/retry' path 'packages/retry-policy'";

test('the path-edit grader accepts the command in any option order and quoting', async () => {
  const grader = await graderFrom('drift-repairs', 'path-edit-for-the-relocated-package');
  const good = [
    MOVE,
    `${MOVE} --json\n`,
    `${MOVE}\r\n`,
    'refs edit toolkit --package @toolkit/retry path packages/retry-policy',
    'refs edit --package="@toolkit/retry" toolkit path --json packages/retry-policy',
    '\n  refs edit toolkit path packages/retry-policy --package=@toolkit/retry  \n\n',
  ];
  deepStrictEqual(await misgraded(grader, good, true), []);
});

test('the path-edit grader fails commands refs rejects or that edit something else', async () => {
  const grader = await graderFrom('drift-repairs', 'path-edit-for-the-relocated-package');
  const bad = [
    // #219's example: the ref after the field pair. refs reads `path` as the ref and exits 4.
    "refs edit --package='@toolkit/retry' path 'packages/retry-policy' 'local/fixtures/toolkit'",
    MOVE.replace("'local/fixtures/toolkit'", 'other'),
    MOVE.replace('packages/retry-policy', 'packages/wrong'),
    MOVE.replace('@toolkit/retry', '@toolkit/slugify'),
    MOVE.replace(" path 'packages/retry-policy'", " --path='packages/retry-policy'"),
    `${MOVE} extra`,
    `${MOVE} --package=@toolkit/slugify`,
    `${MOVE} --json --json`,
    `${MOVE} --remove`,
    `${MOVE} --force`,
    `${MOVE} # move it`,
    `${MOVE} > out`,
    `${MOVE}; true`,
    `${MOVE}\n  touch /tmp/refs-grader-not-run`,
    `# ${MOVE}`,
    `Run ${MOVE}`,
    `\`${MOVE}\``,
    '',
  ];
  deepStrictEqual(await misgraded(grader, bad, false), []);
});

const REMOVE = "refs edit 'local/fixtures/toolkit' --package='@toolkit/slugify' --remove";

test('the removal grader wants the ref as the only positional and nothing else', async () => {
  const grader = await graderFrom('drift-repairs', 'removal-for-the-missing-package');
  const good = [REMOVE, 'refs edit --remove --package @toolkit/slugify toolkit --json\n'];
  deepStrictEqual(await misgraded(grader, good, true), []);
  const bad = [
    `${REMOVE} extra`,
    REMOVE.replace("'local/fixtures/toolkit'", "other 'local/fixtures/toolkit'"),
    `${REMOVE} --package=@toolkit/retry`,
    `${REMOVE} --decline`,
    REMOVE.replace(' --remove', ''),
    `${REMOVE} && echo done`,
  ];
  deepStrictEqual(await misgraded(grader, bad, false), []);
});

const DECLINE =
  "refs edit --package='@toolkit/c$(id)' --decline --path='packages/a b' 'local/fixtures/toolkit'";

test('the decline grader keeps quoted spaces and $() as data and refuses anything more', async () => {
  const grader = await graderFrom('quoted-repair', 'decline-command-is-quoted');
  const good = [
    `${DECLINE}\n`,
    `${DECLINE}\r\n`,
    "refs edit toolkit --decline --package '@toolkit/c$(id)' --path 'packages/a b'",
    String.raw`refs edit --package="@toolkit/c\$(id)" --decline --path="packages/a b" toolkit`,
    String.raw`refs edit --package=@toolkit/c\$\(id\) --decline --path=packages/a\ b toolkit`,
  ];
  deepStrictEqual(await misgraded(grader, good, true), []);
  const bad = [
    `${DECLINE} extra\n`,
    `${DECLINE} --decline`,
    `${DECLINE} --remove`,
    DECLINE.replace("'@toolkit/c$(id)'", "'@toolkit/c'$(id)"),
    DECLINE.replace("'@toolkit/c$(id)'", '"@toolkit/c$(id)"'),
    DECLINE.replace("'packages/a b'", 'packages/a b'),
    DECLINE.replace('local/fixtures/toolkit', 'wrong'),
    DECLINE.replace('--decline', '--decline --package=@x/y'),
    `${DECLINE} # decline it`,
    `${DECLINE} | cat`,
    `${DECLINE}\n  touch /tmp/refs-grader-not-run\n`,
    `# ${DECLINE}`,
  ];
  deepStrictEqual(await misgraded(grader, bad, false), []);
});

test('one-command-only fails any second non-blank line, indented or a comment', async () => {
  const grader = await graderFrom('quoted-repair', 'one-command-only');
  strictEqual(await inFile(grader, `${DECLINE}\n`), true);
  strictEqual(await inFile(grader, `\n  ${DECLINE}  \n\n`), true);
  strictEqual(await inFile(grader, `${DECLINE}\n  touch /tmp/pwned\n`), false);
  strictEqual(await inFile(grader, `${DECLINE}\n# decline it\n`), false);
  strictEqual(await inFile(grader, `${DECLINE} && echo done\n`), false);
});

test('a value with a single quote, a space and $() is one literal word in every spelling', () => {
  const pattern = new RegExp(commandPattern([["it's"]], [['--path', 'a b$(x)']]), 'u');
  const good = [
    String.raw`refs edit 'it'\''s' --path='a b$(x)'`,
    `refs edit 'it'"'"'s' --path 'a b$(x)'`,
    String.raw`refs edit --path="a b\$(x)" "it's"`,
    String.raw`refs edit it\'s --path=a\ b\$\(x\)`,
  ];
  deepStrictEqual(
    good.filter((command) => !pattern.test(command)),
    [],
  );
  const bad = [`refs edit 'it's' --path='a b$(x)'`, `refs edit "it's" --path="a b$(x)"`];
  deepStrictEqual(
    bad.filter((command) => pattern.test(command)),
    [],
  );
});
